// Isometric illustrations for the cleaning page (/sprzatanie), in the same style
// and frame as the flat illustrations (shared engine: scripts/iso.mjs):
//   public/cleaning/klatka.svg         — stairwell
//   public/cleaning/komercyjne.svg     — office (commercial)
//   public/cleaning/niekomercyjne.svg  — classroom (schools and public buildings)
// The post-renovation scene is generated by scripts/build-flat.mjs.
// Run: node scripts/build-cleaning.mjs
import { mkdirSync, writeFileSync } from 'node:fs';
import { P, W, D, H, T, shade, poly, flat, line, onWall, leaves, render, mopBucket, wetSign, cart, vacuum, sparkles } from './iso.mjs';

/** Empty room: slab + two back walls. `wallY` / `wallX` draw on the back walls. */
function room({ floor, wallY = () => '', wallX = () => '' }) {
	const boxes = [];
	const decals = [];
	const overlays = [];
	const box = (tags, x0, x1, y0, y1, z0, z1, color, o = {}) => boxes.push({ tags, x0, x1, y0, y1, z0, z1, color, ...o });
	const decal = (fn) => decals.push({ tags: [], fn });

	box(['structure'], -T, W, -T, D, -0.3, 0, P.ivory, { sideY: P.stone, sideX: shade(P.stone, 0.82), isSlab: true });
	decal(floor);
	box(['wall'], -T, W, -T, 0, 0, H, P.wallFace, { top: P.charcoal, sideY: P.wallFace, extra: wallY });
	box(['wall'], -T, 0, 0, D, 0, H, P.wallFace, { top: P.charcoal, sideX: shade(P.wallFace, 0.86), extra: wallX });

	return { box, decal, overlays, done: () => render(boxes, decals, overlays, () => (c) => c) };
}

const glassWindow = (plane, a0, a1, z0, z1) =>
	onWall(plane, a0, a1, z0, z1, P.glass, ` stroke="${P.charcoal}" stroke-width="2"`) +
	line(plane === 'y' ? [(a0 + a1) / 2, 0, z0] : [0, (a0 + a1) / 2, z0], plane === 'y' ? [(a0 + a1) / 2, 0, z1] : [0, (a0 + a1) / 2, z1], P.charcoal, 1.5) +
	onWall(plane, a0 - 0.1, a1 + 0.1, z0 - 0.08, z0, P.silver);

const tileFloor = (fill, grout, step = 0.5) => () => {
	let s = flat(0, W, 0, D, 0, fill);
	for (let v = step; v < W; v += step) s += line([v, 0, 0], [v, D, 0], grout, 0.6);
	for (let v = step; v < D; v += step) s += line([0, v, 0], [W, v, 0], grout, 0.6);
	return s;
};

const woodFloor = () => {
	let s = flat(0, W, 0, D, 0, P.wood);
	for (let y = 0.35; y < D; y += 0.35) s += line([0, y, 0], [W, y, 0], P.woodDark, 0.6, ' opacity="0.45"');
	return s;
};

/** Freshly mopped floor: a few soft water sheens. */
const wetSheen = (decal, spots) =>
	spots.forEach(([x0, x1, y0, y1]) => decal(() => poly([[x0, y0, 0.004], [x1, y0, 0.004], [x1, y1, 0.004], [x0, y1, 0.004]], P.water, ' opacity="0.75"')));

const plant = (box, x, y, pot = P.bronze, size = 1) =>
	box(['decor'], x, x + 0.42, y, y + 0.42, 0, 0.45, pot, { extra: (c) => leaves(x + 0.21, y + 0.21, 0.85 * size + 0.1, size, c) });

// ---------- 1. stairwell ----------
function stairwell() {
	// Flight runs along the left wall and rises towards the back, so the risers face the viewer.
	const RISE = 0.17;
	const RUN = 0.42;
	const N = 10; // steps below the landing
	const LZ = N * RISE;
	const LY = 2.4; // landing depth
	const FX = 1.5; // flight width

	const r = room({
		floor: tileFloor('#d9d8d3', '#c6c5c0', 0.6),
		wallY: () => {
			let s = '';
			// mailboxes: 4 × 3 grid
			s += onWall('y', 3.4, 5.45, 0.85, 1.75, shade(P.bronze, 0.75));
			for (let i = 0; i < 4; i++)
				for (let j = 0; j < 3; j++) {
					const a = 3.45 + i * 0.5;
					const z = 0.9 + j * 0.28;
					s += onWall('y', a, a + 0.44, z, z + 0.24, P.bronze) + onWall('y', a + 0.08, a + 0.36, z + 0.15, z + 0.19, P.charcoal);
				}
			// entrance door with glass
			s += onWall('y', 6.2, 7.6, 0, 2.25, P.charcoal);
			s += onWall('y', 6.35, 7.45, 0.9, 2.1, P.glass);
			s += onWall('y', 6.4, 6.5, 0.95, 1.15, P.bronze);
			s += glassWindow('y', 8.6, 9.6, 1.3, 2.3);
			return s;
		},
		wallX: () => glassWindow('x', 4.2, 5.6, 1.6, 2.4),
	});
	const { box, decal, overlays } = r;

	const stone = { top: '#e4e3de', sideY: '#c4c2bc', sideX: '#aeaca6' };
	box(['stairs'], 0, 2.9, 0, LY, 0, LZ, '#cfcdc8', stone); // landing
	for (let i = 0; i < N - 1; i++) {
		const y = LY + i * RUN;
		box(['stairs'], 0, FX, y, y + RUN, 0, LZ - (i + 1) * RISE, '#cfcdc8', stone);
	}
	const flightEnd = LY + (N - 1) * RUN;

	// doormat at the entrance and a plant
	decal(() => flat(6.2, 7.6, 0.02, 0.95, 0.006, P.charcoal) + flat(6.28, 7.52, 0.1, 0.87, 0.007, '#3d3d3d'));
	plant(box, 8.0, 0.15, P.charcoal, 1.1);

	// railing: posts and handrail along the open side of the flight and the landing
	let rail = '';
	const RX = FX - 0.06;
	for (let i = 0; i < N - 1; i += 2) {
		const y = LY + i * RUN + 0.2;
		const z = LZ - (i + 1) * RISE;
		rail += line([RX, y, z], [RX, y, z + 0.9], P.charcoal, 2);
	}
	rail += line([RX, LY, LZ + 0.9], [RX, flightEnd - 0.2, RISE + 0.9], P.charcoal, 3);
	rail += line([RX, LY, LZ + 0.9], [2.85, LY, LZ + 0.9], P.charcoal, 3);
	rail += line([2.85, LY, LZ + 0.9], [2.85, 0.05, LZ + 0.9], P.charcoal, 3);
	for (const [x, y] of [[RX, LY], [2.85, LY], [2.85, 1.2]]) rail += line([x, y, LZ], [x, y, LZ + 0.9], P.charcoal, 2);
	overlays.push(rail);

	// cleaning in progress
	wetSheen(decal, [[2.0, 4.2, 3.2, 4.8], [4.4, 6.2, 2.2, 3.2], [2.2, 3.4, 5.4, 6.6]]);
	mopBucket(box, 4.0, 3.6);
	wetSign(box, 2.3, 6.9);
	cart(box, 6.6, 4.4);

	overlays.push(
		sparkles([
			[0.75, LY + 1.2, LZ - 2 * RISE + 0.05, 10],
			[0.75, LY + 2.9, LZ - 6 * RISE + 0.05, 10],
			[1.4, 1.2, LZ + 0.05, 11],
			[4.4, 0, 1.95, 11],
			[6.9, 0, 1.6, 12],
			[3.1, 4.0, 0.05, 9],
		]),
	);
	return r.done();
}

// ---------- 2. office (commercial) ----------
function office() {
	const r = room({
		floor: tileFloor('#dededa', '#d0cfca', 0.5),
		wallY: () => glassWindow('y', 1.6, 3.4, 0.7, 2.25) + glassWindow('y', 4.3, 6.1, 0.7, 2.25) + glassWindow('y', 7.0, 8.8, 0.7, 2.25),
		wallX: () =>
			onWall('x', 1.4, 3.6, 1.05, 2.05, P.white, ` stroke="${P.silver}" stroke-width="2"`) +
			line([0, 1.7, 1.75], [0, 2.9, 1.75], P.bronze, 2) +
			line([0, 1.7, 1.55], [0, 3.2, 1.55], P.stone, 1.5) +
			line([0, 1.7, 1.35], [0, 2.6, 1.35], P.stone, 1.5) +
			onWall('x', 5.2, 6.4, 1.2, 1.95, P.bronze) +
			onWall('x', 5.28, 6.32, 1.27, 1.88, P.ivory) +
			onWall('x', 5.6, 6.0, 1.42, 1.7, P.stone),
	});
	const { box, decal, overlays } = r;

	// rug under the meeting table
	decal(() => flat(1.0, 3.6, 4.6, 7.4, 0.006, P.silver));

	// two pairs of desks, back to back
	const desk = (x, y, face) => {
		box(['desk'], x, x + 1.4, y, y + 0.7, 0.7, 0.75, P.white);
		for (const [lx, ly] of [[x + 0.05, y + 0.05], [x + 1.3, y + 0.05], [x + 0.05, y + 0.6], [x + 1.3, y + 0.6]])
			box(['desk'], lx, lx + 0.05, ly, ly + 0.05, 0, 0.7, P.charcoal);
		const my = face < 0 ? y + 0.12 : y + 0.5;
		box(['desk'], x + 0.45, x + 0.95, my, my + 0.06, 0.75, 1.1, P.charcoal);
		box(['desk'], x + 0.65, x + 0.75, my, my + 0.08, 0.75, 0.8, P.charcoal);
		const cy = face < 0 ? y + 0.85 : y - 0.6;
		box(['chair'], x + 0.45, x + 0.95, cy, cy + 0.48, 0.38, 0.45, P.charcoal);
		box(['chair'], x + 0.66, x + 0.74, cy + 0.2, cy + 0.28, 0, 0.38, P.stone);
		const by = face < 0 ? cy + 0.42 : cy;
		box(['chair'], x + 0.45, x + 0.95, by, by + 0.06, 0.45, 0.95, P.charcoal);
	};
	for (const x of [4.6, 6.2]) {
		desk(x, 1.4, -1);
		desk(x, 2.1, 1);
	}

	// meeting table with chairs
	box(['table'], 1.4, 3.2, 5.3, 6.6, 0.7, 0.76, P.woodDark);
	box(['table'], 2.2, 2.4, 5.85, 6.05, 0, 0.7, P.charcoal);
	for (const [cx, cy] of [[1.6, 4.75], [2.6, 4.75], [1.6, 6.75], [2.6, 6.75]]) box(['chair'], cx, cx + 0.45, cy, cy + 0.45, 0, 0.45, P.silver);

	plant(box, 9.2, 0.3, P.charcoal, 1.15);
	plant(box, 0.25, 0.3, P.bronze, 1);

	// cleaning in progress
	cart(box, 7.6, 5.0);
	vacuum(box, 5.5, 5.4);

	overlays.push(
		sparkles([
			[2.5, 0, 1.9, 12],
			[7.9, 0, 1.6, 12],
			[5.3, 1.75, 0.82, 10],
			[7.0, 2.5, 0.82, 10],
			[2.3, 5.9, 0.82, 10],
			[4.2, 4.6, 0.05, 9],
		]),
	);
	return r.done();
}

// ---------- 3. classroom (schools and public buildings) ----------
function classroom() {
	const r = room({
		floor: woodFloor,
		wallY: () => glassWindow('y', 2.6, 4.2, 0.85, 2.25) + glassWindow('y', 5.2, 6.8, 0.85, 2.25) + glassWindow('y', 7.8, 9.4, 0.85, 2.25),
		wallX: () => {
			let s = onWall('x', 1.3, 5.9, 0.85, 2.05, P.bronze);
			s += onWall('x', 1.38, 5.82, 0.9, 2.0, '#33403a');
			s += line([0, 1.8, 1.7], [0, 3.1, 1.7], P.white, 1.4, ' opacity="0.8"');
			s += line([0, 1.8, 1.5], [0, 3.6, 1.5], P.white, 1.4, ' opacity="0.8"');
			s += line([0, 1.8, 1.3], [0, 2.9, 1.3], P.white, 1.4, ' opacity="0.8"');
			s += onWall('x', 1.4, 5.8, 0.84, 0.88, P.silver);
			s += onWall('x', 6.6, 7.0, 1.95, 2.35, P.white) + line([0, 6.8, 2.15], [0, 6.8, 2.29], P.charcoal, 1.4) + line([0, 6.8, 2.15], [0, 6.9, 2.15], P.charcoal, 1.4);
			return s;
		},
	});
	const { box, decal, overlays } = r;

	// teacher's desk by the board
	box(['desk'], 1.0, 1.7, 2.6, 4.2, 0, 0.75, P.bronze);
	box(['desk'], 0.98, 1.72, 2.58, 4.22, 0.75, 0.8, P.woodDark);

	// three rows of pupils' desks facing the board
	for (const x of [3.3, 5.1, 6.9])
		for (const y of [1.3, 3.2, 5.1]) {
			box(['desk'], x, x + 0.55, y, y + 1.2, 0.68, 0.72, P.white);
			box(['desk'], x + 0.05, x + 0.5, y + 0.05, y + 0.1, 0, 0.68, P.charcoal);
			box(['desk'], x + 0.05, x + 0.5, y + 1.1, y + 1.15, 0, 0.68, P.charcoal);
			for (const cy of [y + 0.1, y + 0.7]) {
				box(['chair'], x + 0.7, x + 1.1, cy, cy + 0.4, 0, 0.42, P.bronze);
				box(['chair'], x + 1.05, x + 1.1, cy, cy + 0.4, 0.42, 0.8, P.bronze);
			}
		}

	plant(box, 9.3, 0.35, P.charcoal, 1.1);

	// cleaning in progress
	mopBucket(box, 8.7, 6.6);
	wetSign(box, 9.1, 3.2);

	overlays.push(
		sparkles([
			[3.6, 1.9, 0.78, 10],
			[5.4, 3.8, 0.78, 10],
			[7.2, 1.9, 0.78, 10],
			[0, 3.6, 2.3, 12],
			[6.0, 0, 1.6, 12],
			[9.0, 5.2, 0.05, 9],
		]),
	);
	return r.done();
}

const outputs = [
	['cleaning/klatka.svg', stairwell(), 'Sprzątanie klatki schodowej'],
	['cleaning/komercyjne.svg', office(), 'Sprzątanie biura — obiekt komercyjny'],
	['cleaning/niekomercyjne.svg', classroom(), 'Sprzątanie sali lekcyjnej — obiekt niekomercyjny'],
];

mkdirSync(new URL('../public/cleaning/', import.meta.url), { recursive: true });
for (const [file, svg, label] of outputs) {
	writeFileSync(new URL(`../public/${file}`, import.meta.url), svg(label));
	console.log(`public/${file}`);
}
